/**
 * Submissions History Component (Standalone)
 * Displays user's code execution history with details
 */

import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CodeExecutionService } from '@core/services/code-execution.service';

interface Submission {
  id: string;
  language: string;
  code: string;
  output: string;
  error: string | null;
  executionTime: number;
  memory: number;
  status: 'success' | 'error' | 'pending';
  createdAt: string;
}

@Component({
  selector: 'app-submissions-history',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './submissions-history.component.html',
  styleUrls: ['./submissions-history.component.css'],
})
export class SubmissionsHistoryComponent implements OnInit {
  submissions: Submission[] = [];
  loading = false;
  error = '';
  expandedIndex: number | null = null;

  constructor(private codeExecutionService: CodeExecutionService) {}

  ngOnInit(): void {
    this.loadSubmissions();
  }

  /**
   * Load submissions from API
   */
  loadSubmissions(): void {
    this.loading = true;
    this.error = '';

    this.codeExecutionService.getSubmissions().subscribe({
      next: (response: any) => {
        const submissions = response.data?.submissions || response.submissions || [];
        this.submissions = submissions.map((sub: any) => ({
          id: sub._id,
          language: sub.language,
          code: sub.code,
          output: sub.output || '',
          error: sub.error || null,
          executionTime: sub.executionTime || 0,
          memory: sub.memory || 0,
          status:
            sub.status === 'completed' ? 'success' : sub.status === 'failed' ? 'error' : 'pending',
          createdAt: sub.createdAt,
        }));
        this.loading = false;
      },
      error: () => {
        this.error = 'Failed to load submissions. Please try again.';
        this.loading = false;
      },
    });
  }

  /**
   * Refresh submissions list
   */
  refreshSubmissions(): void {
    this.loadSubmissions();
  }

  /**
   * Toggle submission details visibility
   */
  toggleSubmission(index: number): void {
    this.expandedIndex = this.expandedIndex === index ? null : index;
  }

  /**
   * Copy code to clipboard
   */
  copyCode(code: string): void {
    navigator.clipboard.writeText(code).catch(() => {
      alert('Failed to copy code');
    });
    alert('Code copied to clipboard!');
  }

  /**
   * Format date to readable string
   */
  formatDate(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  }

  /**
   * Dismiss error message
   */
  dismissError(): void {
    this.error = '';
  }
}
<div class="history-container">
  <div class="history-header">
    <h1>Submission History</h1>
    <button (click)="refreshSubmissions()" class="refresh-btn">🔄 Refresh</button>
  </div>

  <div *ngIf="loading" class="loading">Loading submissions...</div>

  <div *ngIf="error" class="error-message">
    <span>{{ error }}</span>
    <button (click)="dismissError()" class="close-btn">×</button>
  </div>

  <div *ngIf="!loading && submissions.length === 0 && !error" class="loading">
    No submissions yet
  </div>

  <div *ngIf="!loading && submissions.length > 0" class="submissions-list">
    <div *ngFor="let submission of submissions; let i = index" class="submission-item">
      <div class="submission-header" (click)="toggleSubmission(i)">
        <div class="submission-info">
          <span class="language-badge">{{ submission.language }}</span>
          <span [ngClass]="'status-badge ' + submission.status">
            {{ submission.status }}
          </span>
          <span class="submission-date">{{ formatDate(submission.createdAt) }}</span>
        </div>
        <button
          class="expand-btn"
          (click)="toggleSubmission(i); $event.stopPropagation()"
        >
          {{ expandedIndex === i ? '▼' : '▶' }}
        </button>
      </div>

      <div *ngIf="expandedIndex === i" class="submission-details expanded">
        <strong>Code:</strong>
        <pre class="code-block">{{ submission.code }}</pre>
        <button (click)="copyCode(submission.code)" class="copy-btn">📋 Copy Code</button>

        <div *ngIf="submission.output" class="output-block">
          <strong>Output:</strong>
          <pre>{{ submission.output }}</pre>
        </div>

        <div *ngIf="submission.error" class="error-block">
          <strong>Error:</strong>
          <pre>{{ submission.error }}</pre>
        </div>

        <div class="execution-stats">
          <span>⏱️ Execution Time: {{ submission.executionTime }}ms</span>
          <span>💾 Memory: {{ submission.memory }}MB</span>
        </div>
      </div>
    </div>
  </div>
</div>
